local route = {
  {86, 216, 33.2523, 0},
  {-51.3945, 200.918, 32.1582, 0},
  {-1379.22, -563.126, 217.78, 0},
  {-1896.85, -539.33, 163.625, 0},
  {-1896.85, -539.33, 163.625, 30},
  {-1896.85, -539.33, 163.625, 0},
  {-3161.61, -644.018, 160.884, 0},
  {-3175.93, -573.433, 157.806, 15},
  {-3175.93, -573.433, 157.806, 0},
}
local leg = 0
local phase = "new"
local commander_dead = false
local function walk(e, next_leg)
  leg = next_leg
  phase = "walking"
  local p = route[leg]
  e.self:SetRunning(false)
  e.self:MoveTo(p[1], p[2], p[3], 0, true)
end
local function stop_timers()
  eq.stop_timer("pause"); eq.stop_timer("resume"); eq.stop_timer("failure"); eq.stop_timer("leave")
end
local function resume(e)
  -- Death of the commander alone cannot move Corbin away from other attackers.
  if phase ~= "ambush" or not commander_dead or e.self:IsEngaged() then return end
  eq.stop_timer("resume"); eq.stop_timer("failure")
  walk(e, 5)
end
function event_spawn(e)
  if phase == "new" then walk(e, 1) end
end
function event_waypoint_depart(e)
  -- Shared MoveTo delivers this only after its exact authenticated arrival.
  if phase ~= "walking" then return end
  if leg == 3 then e.self:Say("Almost there now, just a bit further...") end
  if leg == 4 then
    phase = "ambush"
    e.self:Say("Uh oh, looks like they were tipped off somehow... I hope you can handle them.")
    local enemy1 = eq.spawn2(116569, 0, 0, -2366, -428, 205, 0)
    enemy1:Signal(7)
    local enemy2 = eq.spawn2(116553, 0, 0, -2364, -448, 205, 0)
    enemy2:Signal(7)
    local enemy3 = eq.spawn2(116553, 0, 0, -2392, -436, 205, 0)
    enemy3:Signal(7)
    local enemy4 = eq.spawn2(116548, 0, 0, -1756, -951, 220, 0)
    enemy4:Signal(7)
    local enemy5 = eq.spawn2(116548, 0, 0, -1780, -935, 220, 0)
    enemy5:Signal(7)
    local enemy6 = eq.spawn2(116553, 0, 0, -1808, -952, 215, 0)
    enemy6:Signal(7)
    local enemy7 = eq.spawn2(116553, 0, 0, -1512, -244, 186, 0)
    enemy7:Signal(7)
    local enemy8 = eq.spawn2(116548, 0, 0, -1487, -262, 188, 0)
    enemy8:Signal(7)
    eq.set_timer("failure", 1200000)
    return
  end
  if leg == 6 then e.self:Say("Well, you're a bit tougher than I had given you credit for. I owe you my life, friend. The camp is right over here.") end
  if leg == 7 then
    eq.depop_with_timer(116118)
    eq.unique_spawn(2000945, 0, 0, -3188, -574, 158, 62)
  end
  if leg == 8 then
    e.self:Say("I have escaped! With the help of our friends here I was saved from certain death. We are in their debt.")
    eq.signal(2000945, 1)
  end
  if leg == 9 then
    phase = "finished"
    eq.signal(2000945, 2)
    eq.set_timer("leave", 30000)
    return
  end
  local pause = route[leg][4]
  if pause > 0 then phase = "paused"; eq.set_timer("pause", pause * 1000)
  else walk(e, leg + 1) end
end
function event_signal(e)
  if e.signal == 7 and phase == "ambush" and not commander_dead then
    commander_dead = true
    eq.set_timer("resume", 1000)
    resume(e)
  end
end
function event_combat(e)
  if not e.joined then resume(e) end
end
function event_timer(e)
  if e.timer == "resume" then resume(e)
  elseif e.timer == "pause" and phase == "paused" then
    eq.stop_timer("pause")
    if e.self:IsEngaged() then eq.set_timer("pause", 1000) else walk(e, leg + 1) end
  elseif (e.timer == "failure" and phase == "ambush") or (e.timer == "leave" and phase == "finished") then
    phase = "ended"; stop_timers(); eq.depop()
  end
end
function event_death_complete(e) phase = "ended"; stop_timers() end
